allowedRequests.query:
query RepositoryInfo($owner: String!, $name: String!) {
  repository(owner: $owner, name: $name) { id name owner { login } defaultBranchRef { name } viewerPermission }
}

fragment pr on PullRequest{number,title,state,url,headRefName,headRepositoryOwner{id,login,...on User{name}},isCrossRepository,isDraft,createdAt}
query PullRequestList($owner: String!, $repo: String!, $limit: Int!, $endCursor: String, $state: [PullRequestState!] = OPEN) {
  repository(owner: $owner, name: $repo) {
    pullRequests(states: $state, first: $limit, after: $endCursor, orderBy: {field: CREATED_AT, direction: DESC}) {
      totalCount nodes { ...pr reviewRequests(first: 9) { nodes { requestedReviewer { ... on User { login } ... on Team { name } } } } }
      pageInfo { hasNextPage endCursor } } } }

# a comment with repository(owner: "evil", name: "x")
query { a: repository(owner: "Owner", name: "App") { ...Info } b: node(id: "PR_app") { ... on PullRequest { title author { login } } }
  rateLimit { remaining } viewer { login }
  d: repository(owner: "owner", name: "app") { parent { id name owner { login } defaultBranchRef { name } viewerPermission } }
  c: repository(owner: "owner", name: "app") { pullRequest(number: 1) { projectItems(first: 9) { nodes { project { title } } } } } }
fragment Info on Repository { id issues(first: 1) { nodes { title } } }

query Q($s: String = """
  block \""" string
""") { viewer { login } }
